'use strict';
function brandMark(){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" role="img" aria-label="APKTrust"><path fill="currentColor" fill-rule="evenodd" d="M26 8H38L60 56H46L41 44H23L18 56H4ZM28 32H36L32 22Z"/><path fill="currentColor" d="M25 49H39V56H25Z"/></svg>`}
const paths={shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z|m8 12 3 3 5-6',plus:'M12 5v14|M5 12h14',grid:'M3 3h7v7H3z|M14 3h7v7h-7z|M3 14h7v7H3z|M14 14h7v7h-7z',scan:'M7 3H3v4|M17 3h4v4|M21 17v4h-4|M7 21H3v-4|M7 12h10|M12 7v10',history:'M3 11a9 9 0 1 1 3 7|M3 4v7h7|M12 7v5l3 2',rules:'M8 3h8l4 4v14H4V3h4|M8 10h8|M8 14h8|M8 18h5',plugin:'M8 3v5|M16 3v5|M6 8h12v4a6 6 0 0 1-12 0V8Z|M12 18v4',box:'m12 3 9 5-9 5-9-5 9-5Z|M3 8v9l9 5 9-5V8|M12 13v9',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',pulse:'M2 12h5l3-8 4 16 3-8h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z|M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16Z|m17 17 5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9|M10 21h4',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16|m14 6 6 6-6 6',refresh:'M20 8a8 8 0 1 0 1 8|M20 3v5h-5',download:'M12 3v12|m7 10 5 5 5-5|M4 16v5h16v-5',copy:'M9 8h11v13H9z|M5 16H3V3h11v2',check:'m5 12 4 4L19 6',circle:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z',checkcircle:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z|m8 12 3 3 5-6',alert:'m12 3 10 18H2L12 3Z|M12 9v5|M12 17v1',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z|M12 11v6|M12 7v1',file:'M5 3h9l5 5v13H5V3Z|M14 3v6h5|M9 13h6|M9 17h6',graph:'M3 3h6v6H3z|M15 15h6v6h-6z|M3 15h6v6H3z|M6 9v6|M9 6h9v9|M9 18h6',network:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z|M3 12h18|M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z',code:'m8 6-6 6 6 6|m16 6 6 6-6 6|m14 3-4 18',lock:'M6 10h12v11H6z|M8 10V6a4 4 0 0 1 8 0v4|M12 14v3',android:'M6 10h12v9H6z|M6 7a6 6 0 0 1 12 0H6Z|M3 10v7|M21 10v7|M8 19v3|M16 19v3|M7 2l-2-2|M17 2l2-2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z|M12 7v5l3 2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z|M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',upload:'M12 16V3|m7 8 5-5 5 5|M4 16v5h16v-5',close:'m5 5 14 14|M19 5 5 19',moon:'M21 14A9 9 0 0 1 10 3a9 9 0 1 0 11 11Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z|M12 1v3|M12 20v3|M1 12h3|M20 12h3|m4 4 2 2|m18 18 2 2|m4 20 2-2|m18 6 2-2',menu:'M3 6h18|M3 12h18|M3 18h18',link:'m9 15 6-6|M8 13l-3 3a3 3 0 0 0 4 4l3-3|M12 7l3-3a3 3 0 0 1 4 4l-3 3',logout:'M9 3H3v18h6|M8 12h13|m17 8 4 4-4 4'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.file).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=n=>n>1024**2?(n/1024**2).toFixed(1)+' MB':n>1024?(n/1024).toFixed(1)+' KB':n+' B';
let state={page:'Upload',scan:null,scans:[],search:'',severity:'all',review:'all',file:null,busy:false,health:null,providers:[],historyUndo:localStorage.getItem('apktrust-history-undo')};
const scanTabs=[['Overview','grid'],['Findings','shield'],['Coverage','pulse'],['Behavior graph','graph'],['Manifest','code'],['Network','network'],['Artifacts','box'],['Dynamic','android'],['Intelligence','spark']];
function conf(c){return `<span class="confidence"><i><b></b><b class="${c==='Low'?'dim':''}"></b><b class="${c!=='High'?'dim':''}"></b></i>${esc(c)}</span>`}
function severity(s){return `<span class="severity ${esc(s)}">${esc(s[0].toUpperCase()+s.slice(1))}</span>`}
function tag(s,cls=''){return `<span class="tag ${cls}">${esc(s)}</span>`}
function toast(text){let el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
async function api(path,options){const r=await fetch('/api/v1'+path,options);const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function navigate(page){state.tablePage=0;state.tableQuery='';clearTimeout(dynamicPoll);if(['Sandbox','System health'].includes(page))loadDynamicHealth();if(page==='Dynamic'){state.dynamic=null;state.dynamicJob=null;loadDynamicHealth();loadDynamic();}if(scanTabs.some(([p])=>p===page)&&!state.scan)page='Upload';if(page==='Providers')api('/providers/status').then(p=>{state.providers=p;if(state.page==='Providers')render()}).catch(e=>toast(e.message));state.page=page;state.search='';state.severity='all';state.review='all';render();window.scrollTo(0,0)}
function shell(){const s=state.scan;const perScan=scanTabs.some(([p])=>p===state.page);return `<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="/">${brandMark()}<span>APK<span>Trust</span></span></a><div class="brand-sub">ANALYST WORKBENCH</div><button class="new-btn" data-action="new">${icon('plus')}New scan</button><div class="nav-label">Workspace</div>${[['Upload','upload','Upload package'],['Scans','history','Scan history'],['Rules','rules','Rules & detection']].map(([p,i,label])=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}">${icon(i)}${label}${p==='Scans'?`<span class="nav-count">${state.scans.length}</span>`:''}</button>`).join('')}<div class="divider"></div><div class="nav-label">Infrastructure</div>${[['Sandbox','box','Dynamic Analysis'],['Providers','spark','AI providers'],['System health','pulse','System health'],['Settings','settings','Settings']].map(([p,i,label])=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}">${icon(i)}${label}</button>`).join('')}<div class="sidebar-bottom"><div class="local-status"><div class="status-line"><span class="dot"></span>Local environment${icon('lock')}</div><p>Local static analysis.<br>Cloud uploads require consent.</p></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu icon-btn" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button>Workspace ${icon('chevron')}<strong>${perScan?'Scans':esc(state.page)}</strong>${perScan?`${icon('chevron')}<span>${esc(s.package.split('.').slice(-2).join('.'))}</span>`:''}</div><div class="top-actions"><button class="search-global" data-action="search" aria-label="Search findings">${icon('search')}<span>Search findings</span><kbd>Ctrl / ⌘ K</kbd></button><button class="icon-btn" aria-label="Toggle color theme" data-action="theme">${icon(document.body.classList.contains('dark')?'sun':'moon')}</button></div></header>${s?.demo&&perScan?`<div class="demo-banner">${icon('info')}Demo investigation · illustrative data, not a real scan.<button data-action="new">Analyze your own APK ${icon('arrow')}</button></div>`:''}<div class="content">${perScan?scanHeader():state.page==='Upload'?'':pageHeader()}${perScan?tabs():''}<div id="page-content">${pageContent()}</div><footer class="page-foot"><div class="footer-brand">${brandMark()}<div><strong>APKTrust <small>v0.4.0</small></strong><span>Local evidence workbench</span></div></div><div class="footer-context">${icon('lock')}Cloud APK uploads require consent</div><button class="btn ghost" data-page="System health">System health ${icon('arrow')}</button></footer></div></main></div>`}
function scanHeader(){let s=state.scan;return `<div class="page-heading"><div><div class="eyebrow">Package investigation</div><h1>${state.page==='Overview'?'Scan overview':esc(state.page)}</h1></div><div class="heading-actions"><button class="btn" data-action="rerun">${icon('refresh')}New scan</button><button class="btn primary" data-action="export">${icon('download')}Export report${icon('down')}</button></div></div><div class="package-strip"><div class="app-icon">${icon(s.demo?'pulse':'android')}</div><div><div class="package-name">${esc(s.demo?'BeatWave':s.package)}<span class="version">v${esc(s.version)}</span>${tag(s.demo?'Demo sample':s.format||'APK','gray')}</div><div class="package-meta"><span>${bytes(s.size)}</span><span>·</span><button data-action="copy" aria-label="Copy SHA-256">${icon('copy')}SHA-256: ${esc(s.sha256.slice(0,12))}…</button></div></div><div class="package-right"><div><div class="label">Scan profile</div><div class="value">${icon('shield')}${s.pipeline?'Combined investigation':'Static analysis'}</div></div><div><div class="label">Scan status</div><div class="value">${tag(s.demo?'Demo · partial':s.pipeline?(s.pipeline.state==='COMPLETED'?'Checks complete':'Completed with gaps'):s.state==='PARTIAL'?'Partial analysis':s.state,s.state==='PARTIAL'&&!s.demo?'orange':'')}${icon('clock')} ${s.demo?'3m 04s':s.duration+'s'+(s.pipeline?' total':' static')}</div></div><div><div class="label">Analyzed</div><div class="value">${s.demo?'Example investigation':new Date(s.created*1000).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}</div></div></div></div>`}
function tabs(){return `<nav class="tabs" aria-label="Scan sections">${scanTabs.map(([p,i])=>`<button class="tab ${state.page===p?'active':''}" data-page="${p}">${icon(i)}${p}${p==='Findings'?`<span class="tab-count">${state.scan.findings.length}</span>`:''}</button>`).join('')}</nav>`}
function pageHeader(){const subtitles={'Scans':'Your investigations, preserved locally. Pick up where you left off.','Rules':'Deterministic signals with explicit evidence and confidence.','Plugins':'Extend analysis through carefully scoped capabilities.','Sandbox':'Optional remote execution with explicit cloud-upload consent.','Upload':'Analyze an Android package before you install it.','Providers':'Optional explanations. Deterministic evidence always owns the verdict.','System health':'A transparent view of this workstation’s analysis capabilities.','Settings':'Make this workbench yours.'};return `<div class="page-heading"><div><div class="eyebrow">Workspace / ${esc(state.page)}</div><h1>${state.page==='Scans'?'Scan history':state.page==='Upload'?'Understand before you install.':esc(state.page)}</h1><p>${subtitles[state.page]||''}</p></div>${state.page==='Scans'?`<div class="heading-actions"><button class="btn" data-action="clear-history" ${state.scans.length?'':'disabled'}>${icon('close')}Clear history</button><button class="btn primary" data-action="new">${icon('plus')}New scan</button></div>`:''}</div>`}
function findingRows(findings,full=false){return findings.map(f=>`<tr class="finding-row" data-finding="${esc(f.id)}" tabindex="0" aria-label="Open ${esc(f.title)}"><td>${severity(f.severity)}</td><td><div class="finding-title">${esc(f.title)}</div><div class="finding-category">${esc(f.category)} ${f.origin==='Dynamic'?tag('DYNAMIC · Firebase Test Lab'):tag('STATIC','gray')}${f.component?' · '+esc(f.component):''}</div></td><td>${conf(f.confidence)}</td><td><span class="evidence-count">${icon('file')}${f.evidence.length}${full?' evidence':''}</span></td>${full?`<td>${tag(f.status,f.status==='Dismissed'?'gray':'')}</td>`:''}<td>${icon('chevron')}</td></tr>`).join('')}
function vtEvidenceSnapshot(s){
 const collection=s.vt_intelligence;if(!collection)return '';
 const groups=collection.groups||[],file=groups.find(g=>g.id==='VT-FILE')?.data||{},stats=file.last_analysis_stats||s.reputation?.results?.find(r=>r.provider==='virustotal')?.stats||{};
 const malicious=Number(stats.malicious)||0,suspicious=Number(stats.suspicious)||0,undetected=Number(stats.undetected)||0,harmless=Number(stats.harmless)||0,total=malicious+suspicious+undetected+harmless;
 const available=groups.filter(g=>g.status==='AVAILABLE').length,limited=groups.filter(g=>!['AVAILABLE','NO_DATA'].includes(g.status)).length;
 const type=file.type_description||file.meaningful_name||s.reputation?.results?.find(r=>r.provider==='virustotal')?.file_metadata?.type_description||'File metadata unavailable';
 return `<section class="panel vt-overview"><div class="panel-head"><div><h2>VirusTotal snapshot</h2><div class="panel-sub">External reputation evidence · ${available} evidence groups available</div></div>${tag(collection.status||'UNKNOWN',collection.status==='COMPLETE'?'':'orange')}</div><div class="vt-overview-grid"><div class="vt-overview-verdict"><div class="vt-verdict-number">${malicious}<span> malicious detections</span></div><div class="vt-verdict-track" role="img" aria-label="${malicious} malicious, ${suspicious} suspicious of ${total} reported engine verdicts"><i class="bad" style="width:${total?malicious/total*100:0}%"></i><i class="warn" style="width:${total?suspicious/total*100:0}%"></i></div><div class="vt-verdict-legend"><span>${malicious} malicious</span><span>${suspicious} suspicious</span><span>${total} engine verdicts</span></div></div><div class="vt-overview-facts"><div><span>File type</span><strong>${esc(type)}</strong></div><div><span>Android analysis</span><strong>${file.androguard?'Available':'No report data'}</strong></div><div><span>Sandbox</span><strong>${groups.find(g=>g.id==='VT-SANDBOXES')?.status==='AVAILABLE'?(groups.find(g=>g.id==='VT-SANDBOXES').data||[]).length+' report(s)':'Unavailable'}</strong></div>${limited?`<div><span>Access gaps</span><strong>${limited} group(s)</strong></div>`:''}</div></div><div class="vt-overview-foot"><span>Existing VT report. Zero detections do not guarantee safety.</span><button class="btn ghost" data-page="Intelligence">Review VT evidence ${icon('arrow')}</button></div></section>`;
}
function vtFieldLabel(key){return String(key).replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase())}
function vtEngineResults(items){const rows=Object.entries(items||{}).map(([name,v])=>({name,result:v?.result||'—',category:v?.category||'unknown',method:v?.method||'',version:v?.engine_version||''})).sort((a,b)=>({malicious:0,suspicious:1,harmless:2,undetected:3,timeout:4,'type-unsupported':5,failure:6}[a.category]??7)-({malicious:0,suspicious:1,harmless:2,undetected:3,timeout:4,'type-unsupported':5,failure:6}[b.category]??7));const hits=rows.filter(x=>['malicious','suspicious'].includes(x.category));const visible=hits.length?hits:rows.slice(0,8);return `<div class="vt-engine-summary">${hits.length?`<p>${hits.length} engine(s) flagged this file</p>`:'<p>No malicious or suspicious engine verdicts in the displayed report.</p>'}<div class="table-wrap"><table><thead><tr><th>Engine</th><th>Category</th><th>Detection label</th></tr></thead><tbody>${visible.slice(0,12).map(x=>`<tr><td>${esc(x.name)}</td><td>${tag(x.category,x.category==='malicious'?'red':x.category==='suspicious'?'orange':'gray')}</td><td>${esc(x.result)}</td></tr>`).join('')}</tbody></table></div>${rows.length>visible.length?`<details class="vt-nested"><summary>Show all ${rows.length} engine results</summary><div class="table-wrap"><table><thead><tr><th>Engine</th><th>Category</th><th>Detection label</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.category)}</td><td>${esc(x.result)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`}
function vtEvidenceValue(value,depth=0){
 if(value===null||value===undefined)return '<span class="vt-empty-value">Not reported</span>';
 if(typeof value==='string'||typeof value==='number'||typeof value==='boolean')return `<span>${esc(value)}</span>`;
 if(Array.isArray(value)){if(!value.length)return '<span class="vt-empty-value">None reported</span>';if(value.every(x=>typeof x!=='object'||x===null))return `<div class="vt-chip-list">${value.slice(0,12).map(x=>tag(String(x),'gray')).join('')}${value.length>12?tag('+'+(value.length-12)+' more','gray'):''}</div>`;return `<div class="vt-record-list">${value.slice(0,8).map((item,i)=>`<article class="vt-record"><strong>${esc(item?.sandbox_name||item?.observable||item?.type||'Record '+(i+1))}</strong>${vtEvidenceValue(item,depth+1)}</article>`).join('')}${value.length>8?`<p class="intel-caption">${value.length-8} more records available in the export.</p>`:''}</div>`}
 if(depth>2)return `<span class="vt-empty-value">Structured data available in JSON export (${Object.keys(value).length} fields)</span>`;
 const entries=Object.entries(value).filter(([,v])=>v!==null&&v!==undefined);if(!entries.length)return '<span class="vt-empty-value">No fields reported</span>';
 if(entries.length>30)return `<details class="vt-nested"><summary>${entries.length} detailed records</summary>${entries.slice(0,30).map(([k,v])=>`<div class="vt-data-row"><span>${esc(vtFieldLabel(k))}</span><div>${k==='last_analysis_results'&&v&&typeof v==='object'?vtEngineResults(v):vtEvidenceValue(v,depth+1)}</div></div>`).join('')}<p class="intel-caption">Showing 30 of ${entries.length}; full response is in the JSON export.</p></details>`;
 return `<div class="vt-data-rows">${entries.map(([k,v])=>`<div class="vt-data-row"><span>${esc(vtFieldLabel(k))}</span><div>${k==='last_analysis_results'&&v&&typeof v==='object'?vtEngineResults(v):vtEvidenceValue(v,depth+1)}</div></div>`).join('')}</div>`;
}
function vtEvidencePanel(s){const c=s.vt_intelligence;if(!c)return '';const groups=c.groups||[],ai=s.ai_explanation,aiReceived=ai?.provider&&ai.provider!=='local'&&ai.input_scope?.vt_evidence&&(!ai.created||ai.created>=c.checked),statuses={AVAILABLE:'Available',NO_DATA:'No report',ACCESS_DENIED:'Access restricted',RATE_LIMITED:'Rate limited',UNAVAILABLE:'Unavailable',NOT_QUERIED:'Not queried'};return `<section class="panel panel-spaced"><div class="panel-head"><div><h2>VirusTotal evidence</h2><div class="panel-sub">File analysis, engine verdicts, Android metadata, sandbox reports and related observables</div></div>${tag(c.status||'Unknown',c.status==='COMPLETE'?'':'orange')}</div><div class="intel-detail-body"><div class="vt-evidence-intro"><span>${icon('info')}</span><p>Evidence from the existing VirusTotal report. Each section shows what the provider returned and where access was limited.</p></div><div class="vt-evidence-groups">${groups.map(g=>`<details class="vt-data-group"><summary><span class="vt-group-title">${esc(g.label)}</span><span class="vt-group-meta">${tag(statuses[g.status]||g.status,g.status==='AVAILABLE'?'':g.status==='NO_DATA'?'gray':'orange')}${g.truncated?tag('More pages','orange'):''}</span></summary><div class="vt-group-body">${g.detail?`<p class="vt-group-note">${esc(g.detail)}</p>`:''}${g.status==='AVAILABLE'?vtEvidenceValue(g.data):g.status==='NO_DATA'?'<p class="vt-empty-value">VirusTotal has no report for this evidence category.</p>':g.status==='ACCESS_DENIED'?'<p class="vt-empty-value">The current API access does not include this evidence category.</p>':g.status==='RATE_LIMITED'?'<p class="vt-empty-value">Request limit reached. This category and later categories were not collected.</p>':g.status==='NOT_QUERIED'?'<p class="vt-empty-value">Not requested because the provider limit was reached earlier.</p>':'<p class="vt-empty-value">Provider did not return this evidence.</p>'}${g.normalized_or_limited||g.truncated?'<p class="intel-caption">Some fields or records were limited before display. Open the JSON export for the full saved response.</p>':''}</div></details>`).join('')}</div><div class="vt-ai-note">${icon('spark')}<p><strong>${aiReceived?'Used in last AI synthesis · '+esc(providerLabel(ai.provider)):'Not confirmed in the last hosted AI synthesis'}</strong><br>${aiReceived?'That AI run received the VT category statuses and normalized evidence. Larger sections may have been shortened to fit its context; see per-section limit notes above.':'The last explanation was local, did not run, or predates this VT collection. Select Regenerate intelligence to include the currently collected VT data.'} Credentials, raw source, screenshots and request bodies are excluded.</p></div><p class="intel-caption">VirusTotal evidence is provider-reported context. It does not replace APKTrust static findings or constitute full runtime instrumentation.</p></div></section>`}
function overview(){const s=state.scan;return `${enrichmentPage(true)}<section class="review-metrics" aria-label="Investigation metrics"><div><span>Assessment</span><strong>${esc(s.risk)}</strong></div><div><span>Confidence</span><strong>${esc(s.confidence)}</strong></div><div><span>Static stage completion</span><strong>${s.coverage_percent}% <button data-page="Coverage">View gaps ${icon('arrow')}</button></strong></div><div><span>Findings</span><strong>${s.findings.length} <small>${s.findings.filter(f=>f.status==='Needs review').length} to review</small></strong></div></section>${overviewCharts(s)}${vtEvidenceSnapshot(s)}<section class="panel"><div class="panel-head"><div><h2>Priority evidence</h2><div class="panel-sub">Inspect the evidence behind each finding.</div></div><button class="btn" data-page="Findings">All findings ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>Severity</th><th>Finding</th><th>Confidence</th><th>Evidence</th><th></th></tr></thead><tbody>${findingRows([...s.findings].sort((a,b)=>({critical:0,high:1,medium:2,low:3,info:4}[a.severity]??5)-({critical:0,high:1,medium:2,low:3,info:4}[b.severity]??5)).slice(0,5))}</tbody></table>${s.findings.length?'':'<div class="empty"><p>No signals in completed checks. Review the remaining analysis gaps.</p></div>'}</div></section>`}

function findings(){return `<section class="panel"><div class="panel-head"><h2>All findings</h2>${tag(state.scan.findings.length+' findings','gray')}</div><div class="filters"><label class="input-wrap">${icon('search')}<input id="finding-search" placeholder="Search title, category, rule or evidence…" aria-label="Search findings" value="${esc(state.search)}"></label><select id="severity-filter" aria-label="Filter severity"><option value="all">All severities</option>${['high','medium','low','info'].map(x=>`<option value="${x}" ${state.severity===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select><select id="review-filter" aria-label="Filter review status"><option value="all">All review states</option>${['Needs review','Confirmed','Dismissed'].map(x=>`<option ${state.review===x?'selected':''}>${x}</option>`).join('')}</select></div><div id="finding-results">${filteredFindings()}</div></section>`}
function filteredFindings(){const q=state.search.toLowerCase();let fs=state.scan.findings.filter(f=>(state.severity==='all'||f.severity===state.severity)&&(state.review==='all'||f.status===state.review)&&JSON.stringify(f).toLowerCase().includes(q));return `<div class="table-wrap"><table><thead><tr><th>Severity</th><th>Finding / category</th><th>Confidence</th><th>Evidence</th><th>Review status</th><th></th></tr></thead><tbody>${findingRows(fs,true)}</tbody></table>${fs.length?'':`<div class="empty">${icon('search')}<h2>No matching findings</h2><p>Adjust your filters or try another search.</p></div>`}</div><div class="table-footer"><span>Showing ${fs.length} of ${state.scan.findings.length} findings</span><span>Click a row to trace its evidence</span></div>`}
function packageSetPanel(s){if(!s.package_splits?.length)return '';return `<section class="panel package-set-panel"><div class="panel-head"><h2>Package set · ${esc(s.format)}</h2>${tag(s.package_splits.length+' APK components','gray')}</div><div class="table-wrap"><table><thead><tr><th>Component / role</th><th>Package / version</th><th>Analysis</th><th>Stage completion</th><th>SHA-256</th></tr></thead><tbody>${s.package_splits.map(p=>`<tr><td class="mono">${esc(p.path)}<div class="finding-category">${esc(p.role)}${p.split_name?' · '+esc(p.split_name):''}</div></td><td>${esc(p.package)}<div class="finding-category">v${esc(p.version)}</div></td><td>${tag(p.status,p.status==='Failed'?'red':'orange')}<div class="finding-category">${esc(p.error||p.findings+' findings; advanced analyses not run')}</div></td><td>${p.coverage_percent}%</td><td class="mono">${esc(p.sha256?.slice(0,12)||'Unavailable')}…</td></tr>`).join('')}</tbody></table></div><div class="table-footer">All bundled APK variants are inventoried. Signature consistency and device-specific installability remain unverified. OBB/assets are listed in Artifacts.</div></section>`}
function coverage(){let s=state.scan;return `${packageSetPanel(s)}<div class="notice">${icon('info')}<div><strong>Unknown stays unknown.</strong> ${s.demo?'This is an illustrative ledger.':'Coverage measures completed stages, not the proportion of code proven safe.'} Byte indexing does not replace decompilation, call tracing, signing verification, or runtime analysis.</div></div><section class="panel"><div class="panel-head"><h2>Analysis coverage ledger</h2>${tag('Partial investigation','orange')}</div><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Analyzer</th><th>Status</th><th>Analyzed / total</th><th>Scope & limitations</th></tr></thead><tbody>${s.coverage.map(c=>`<tr><td>${esc(c.name)}</td><td>${tag(c.status,c.status==='Complete'?'':c.status==='Partial'?'orange':'gray')}</td><td class="mono">${c.analyzed} / ${c.total}</td><td>${esc(c.detail)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel panel-spaced"><div class="panel-head"><h2>Known limitations</h2></div><div class="settings-list">${s.limitations.map(x=>`<div class="setting"><p>${esc(x)}</p></div>`).join('')}</div></section>`}
function graph(){return state.scan.demo?`<div class="notice">${icon('info')}Illustrative behavior chain. These relationships are supplied by the demo fixture and are not generated from uploaded APKs.</div><section class="panel"><div class="panel-head"><h2>APK updater · behavior chain</h2><button class="btn ghost" data-finding="F-003">Open finding ${icon('arrow')}</button></div><div class="graph-canvas"><div class="graph-chain">${[['SOURCE','Release endpoint','github.com / releases'],['WRITE','Cached APK','app cache / update.apk'],['SINK','Package installer','Explicit user approval']].map(([type,title,p],i)=>`${i?'<span class="graph-arrow">→</span>':''}<div class="graph-node"><small>${type}</small><h3>${title}</h3><p>${p}</p></div>`).join('')}</div></div><div class="table-footer"><span>2 evidence objects · illustrative call relationships</span><span>Static / demo fixture</span></div></section>`:`<section class="panel"><div class="empty">${icon('graph')}<h2>Behavior relationships remain unknown</h2><p>This scanner indexes byte references. It cannot establish calls or data flow.<br>A decompiler and graph analyzer are required before drawing a chain.</p><button class="btn" data-page="Coverage">Inspect analysis gaps ${icon('arrow')}</button></div></section>`}
function manifest(){const s=state.scan;return `<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Package identity</h2>${icon('android')}</div>${[['Package',s.package],['Version',s.version],['Minimum / target SDK',(s.min_sdk??'Unknown')+' / '+(s.target_sdk??'Unknown')],['Signature',s.signer],['File',s.filename],['SHA-256',s.sha256]].map(([k,v])=>`<div class="kv"><span>${k}</span><strong class="${k==='SHA-256'?'mono':''}">${esc(v)}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Declared permissions</h2>${tag(s.permissions.length,'gray')}</div>${s.permissions.map(p=>{const details=(s.permission_details||[]).filter(d=>d.name===p);return `<div class="kv"><div><strong class="mono">${esc(p.replace('android.permission.',''))}</strong>${details.some(d=>d.max_sdk)?`<p>Maximum SDK: ${esc(details.filter(d=>d.max_sdk).map(d=>d.max_sdk).join(', '))}</p>`:''}</div>${tag(details[0]?.protection||'Declared','gray')}</div>`}).join('')||'<div class="empty"><p>No permissions available. Check manifest coverage.</p></div>'}<div class="table-footer">Declarations do not establish runtime grants or usage. Unknown protection levels remain unresolved.</div></section></div><section class="panel panel-spaced"><div class="panel-head"><h2>Components / IPC</h2>${tag(s.components.length+' components','gray')}</div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Type</th><th>Export assessment</th><th>Effective permission</th><th>Guard</th></tr></thead><tbody>${s.components.map(c=>`<tr><td class="mono">${esc(c.name)}${c.artifact?`<small>${esc(c.artifact)}</small>`:''}</td><td>${esc(c.type)}</td><td>${tag(c.effective_exported===true?'Exported':c.effective_exported===false?'Internal':c.exported||'Unknown',c.enabled!==false&&c.effective_exported===true&&c.permission_protection==='None'?'orange':'gray')}<small>${esc(c.export_basis||'Explicit declaration only')}${c.enabled===false?' · Disabled':''}</small></td><td>${esc(c.permission||'No general guard')}${c.type==='provider'?`<small>Read: ${esc(c.read_permission||'No guard')}<br>Write: ${esc(c.write_permission||'No guard')}</small>`:''}</td><td>${esc(c.permission_protection||'Unknown')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">Application-level permissions and legacy export defaults are considered. Provider path permissions, URI grants, caller checks and runtime reachability still need review.</div></section>${s.static_analysis_gaps?.length?`<section class="panel panel-spaced"><div class="panel-head"><h2>Manifest / configuration gaps</h2>${tag('Incomplete','orange')}</div><div class="settings-list">${s.static_analysis_gaps.map(g=>`<div class="setting"><p>${esc(g)}</p></div>`).join('')}</div></section>`:''}`}

function network(){return `${vtNetworkPanel()}<div class="notice">${icon('network')}Static endpoints below are string references, separate from VirusTotal observations.</div><section class="panel"><div class="panel-head"><h2>Static endpoint inventory</h2>${tag(state.scan.endpoints.length+' references','gray')}</div>${inventoryControls('Search URL or source artifact')}<div id="inventory-results">${inventoryRows('network')}</div></section>`}
function artifacts(){return `<section class="panel"><div class="panel-head"><h2>Immutable package inventory</h2>${tag(state.scan.inventory.length+' files','gray')}</div>${inventoryControls('Search artifact path, kind or coverage')}<div id="inventory-results">${inventoryRows('artifacts')}</div></section>`}
function inventoryControls(label){return `<div class="filters"><label class="input-wrap">${icon('search')}<input id="inventory-search" aria-label="${label}" placeholder="${label}" value="${esc(state.tableQuery||'')}"></label></div>`}
function inventoryRows(kind){const query=(state.tableQuery||'').toLowerCase(),items=(kind==='network'?state.scan.endpoints:state.scan.inventory).filter(x=>Object.values(x).join(' ').toLowerCase().includes(query)),pages=Math.max(1,Math.ceil(items.length/40));state.tablePage=Math.min(state.tablePage||0,pages-1);const rows=items.slice(state.tablePage*40,(state.tablePage+1)*40);return `<div class="table-wrap"><table><thead><tr>${(kind==='network'?['Endpoint','Protocol','Source artifact','Evidence type']:['Artifact path','Kind','Size','Coverage','Scope']).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>kind==='network'?`<tr><td class="mono">${esc(x.url)}</td><td>${tag(x.scheme.toUpperCase(),x.scheme==='http'?'orange':'')}</td><td class="mono">${esc(x.path)}</td><td>${esc(x.status)}</td></tr>`:`<tr><td class="mono">${esc(x.path)}</td><td>${esc(x.kind)}</td><td>${bytes(x.size)}</td><td>${tag(x.status,['Skipped','Failed'].includes(x.status)?'orange':'gray')}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty"><h3>No matching records</h3><p>Try a different search. Unobserved behavior remains unknown.</p></div>'}</div><div class="table-footer"><span>${items.length} matching records · page ${state.tablePage+1} of ${pages}</span><div class="pagination"><button class="btn" data-table-prev ${state.tablePage===0?'disabled':''}>Previous</button><button class="btn" data-table-next ${state.tablePage>=pages-1?'disabled':''}>Next</button></div></div>`}
function bindInventory(){const kind=state.page==='Network'?'network':'artifacts',input=document.querySelector('#inventory-search'),results=document.querySelector('#inventory-results');if(!input||!results)return;const bindPages=()=>{document.querySelector('[data-table-prev]').onclick=()=>{state.tablePage--;refresh()};document.querySelector('[data-table-next]').onclick=()=>{state.tablePage++;refresh()}};const refresh=()=>{results.innerHTML=inventoryRows(kind);bindPages()};input.oninput=()=>{state.tableQuery=input.value;state.tablePage=0;refresh()};bindPages()}

function history(){return `${state.historyUndo?`<div class="notice">${icon('info')}<span>History cleared. Reports can be restored.</span><button class="btn" data-action="undo-history">Undo clear</button></div>`:''}<div class="notice">${icon('refresh')}Every upload launches a fresh analyzer process. History is saved reports—not a scan cache. Fast results reflect bounded analysis; static decompilation is not performed. Optional remote dynamic execution has its own timeline.</div><section class="panel"><div class="panel-head"><h2>Recent investigations</h2>${tag(state.scans.length+' local scans','gray')}</div>${state.scans.map(s=>`<button class="scan-card full-width" ${s.pipeline?.state==='RUNNING'?'data-resume="'+esc(s.id)+'"':'data-scan="'+esc(s.id)+'"'}><div class="app-icon">${icon(s.demo?'pulse':'android')}</div><div class="scan-info"><h3>${esc(s.package)} ${tag(s.demo?'Demo':'Local','gray')}</h3><p>${esc(s.filename)} · ${bytes(s.size)} · ${s.demo?'Example investigation':new Date(s.created*1000).toLocaleString()}</p></div>${tag(s.pipeline?.state==='RUNNING'?'Running':s.risk,'orange')}<span class="confidence">${s.pipeline?.state==='RUNNING'?'Follow progress':s.coverage_percent+'% stage completion'}</span>${icon('chevron')}</button>`).join('')}</section>`}
function rules(){const rows=state.ruleCatalog||[];return `<div class="notice">${icon('shield')}Deterministic manifest/configuration checks and bounded reference signals. High confidence describes a declaration, not malicious intent. Code references remain low confidence.</div><section class="panel"><div class="panel-head"><h2>Built-in static rules</h2>${tag(rows.length+' rules','gray')}</div><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Assessment</th><th>Evidence level</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mono">${esc(r.id)}</td><td>${esc(r.title)}<small>${esc(r.category)}</small></td><td>${esc(r.evidence_tier==='MANIFEST_CONFIG'?'Manifest / XML configuration':'Byte reference')}</td><td>${tag(r.status)}</td></tr>`).join('')||'<tr><td colspan="4">Rule catalog unavailable. Restart APKTrust after updating, then refresh.</td></tr>'}</tbody></table></div></section>`}

function providersPage(){const scan=state.scan||{demo:true,format:'',filename:''};const ai=state.providers.filter(p=>['groq','openrouter','gemini'].includes(p.id)),intel=state.providers.filter(p=>['urlhaus','virustotal'].includes(p.id));function row(p){return `<div class="setting provider-row"><div><h3>${esc(p.name)} ${tag(p.configured?'Key configured':'Key missing',p.configured?'':'gray')}</h3>${p.id==='virustotal'?`<p>${esc(p.key_count||0)} unique key(s) configured · ${esc((p.key_slots||[]).map(k=>'Key '+k.slot+': '+k.status.replaceAll('_',' ')).join(' · '))}</p>`:''}<p class="mono">${esc(p.key_variable)}${p.model?' · '+esc(p.model):''}</p><p>${p.last_test?esc(p.last_test.status+' · '+p.last_test.detail):'Not tested in this workbench'}</p></div><button class="btn" data-provider-test="${p.id}" ${p.configured?'':'disabled'}>${icon('pulse')}Test connection</button></div>`}return `<div class="notice">${icon('lock')}Keys are read server-side from the local .env file or environment variables. They are never returned to the browser. Connection tests send a fixed probe and use API quota. Scan enrichment follows the options selected at upload.</div><section class="panel"><div class="panel-head"><h2>AI routing · Groq → OpenRouter → Gemini → local</h2>${tag('Opt-in','gray')}</div><div class="settings-list">${ai.map(row).join('')}</div></section><section class="panel panel-spaced"><div class="panel-head"><h2>Threat intelligence</h2>${tag('Hash lookup only','gray')}</div><div class="settings-list">${intel.map(row).join('')}</div></section><section class="panel panel-spaced"><div class="panel-head"><h2>Local configuration</h2></div><div class="settings-list"><div class="setting"><div><h3>Edit the .env beside server.py</h3><p>Paste each key after its matching variable. Use one variable per line. Models follow your test report; availability is checked by Test connection. Refresh this page after saving—no server restart needed.</p><pre class="config-preview">GROQ_API_KEY=your_key
OPENROUTER_API_KEY=your_key
GEMINI_API_KEY=your_key
URLHAUS_AUTH_KEY=your_key
VT_API_KEY=your_first_key
VT_API_KEY_2=your_second_key
VT_API_KEY_3=your_third_key</pre><p>No key-entry form is exposed to the browser. Keep this file local.</p></div></div></div></section><section class="panel panel-spaced"><div class="panel-head"><h2>Enrich selected investigation</h2>${tag(scan.demo?'Select a real scan':scan.format||'APK','gray')}</div><div class="settings-list"><div class="setting"><div><h3>${esc(scan.demo?'No investigation selected':scan.filename)}</h3><p>Choose a scan in Scan history first. AI receives normalized evidence and accessible VT metadata/observables, excluding credentials, raw source and APK bytes. Hash lookup sends the top-level SHA-256 to VirusTotal and URLhaus, not the APK file.</p></div></div><div class="setting enrichment-actions"><button class="btn primary" data-enrich="ai/explain" ${scan.demo?'disabled':''}>${icon('spark')}Send minimal summary to AI</button><button class="btn" data-enrich="reputation" ${scan.demo?'disabled':''}>${icon('shield')}Look up SHA-256 externally</button></div></div></section>`}
function providerLabel(id){return ({groq:'Groq',openrouter:'OpenRouter',gemini:'Gemini',firebase_test_lab:'Firebase Test Lab','mock-ai':'Mock AI'})[id]||String(id||'Provider').replaceAll('_',' ')}
function stageSnapshot(s){
 if(s.pipeline?.stages)return s.pipeline.stages;
 const a=s.ai_explanation,r=s.reputation,d=Object.values(s.dynamic_results||{}).at(-1);
 return {static:{status:'COMPLETED',detail:'Bounded static checks'},reputation:{status:r?.results?.some(x=>x.status==='FOUND'||x.status==='NOT_FOUND')?'COMPLETED':r?'FAILED':'SKIPPED',detail:r?'Existing hash lookups':'Not requested in this earlier scan'},dynamic:{status:d?.status==='COMPLETED'?'COMPLETED':d?'FAILED':'SKIPPED',detail:d?'Limited Robo coverage':'No runtime execution'},ai:{status:a?.provider&&a.provider!=='local'?'COMPLETED':a?'FAILED':'SKIPPED',detail:a?.provider==='local'?'Local fallback; hosted AI unavailable':a?'Hosted summary':'Not requested in this earlier scan'}};
}
function stageBadge(status){return tag(({COMPLETED:'Completed',SKIPPED:'Skipped',FAILED:'Unavailable',PENDING:'Waiting',RUNNING:'Running'})[status]||status,status==='COMPLETED'?'':status==='FAILED'?'orange':'gray')}
function intelligenceList(title,items){return items?.length?`<div class="intel-section"><h3>${title}</h3><ul>${items.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}
function reputationCards(s){
 const results=s.reputation?.results||[];
 return `<div class="intel-reputation-grid">${['virustotal','urlhaus'].map(id=>{
 const r=results.find(x=>x.provider===id),stats=r?.stats||{},flagged=(stats.malicious||0)+(stats.suspicious||0),verdicts=flagged+(stats.undetected||0)+(stats.harmless||0),unsupported=stats['type-unsupported']||0;
 const found=r?.status==='FOUND',missing=r?.status==='NOT_FOUND';
 const headline=id==='virustotal'&&found&&verdicts>0?`<strong>${flagged}</strong><span>flagged / ${verdicts} engine verdicts</span>`:`<strong class="intel-word">${missing?'No matching record':found?(id==='virustotal'?'No engine verdicts':'Record found'):r?.status==='NOT_CONFIGURED'?'Key not configured':r?'Lookup unavailable':'Not queried'}</strong>`;
 return `<article class="intel-provider"><div class="intel-provider-head"><span class="provider-mark">${icon(id==='virustotal'?'scan':'network')}</span><h3>${id==='virustotal'?'VirusTotal':'URLhaus'}</h3>${stageBadge(found||missing?'COMPLETED':r?.status==='FAILED'?'FAILED':'SKIPPED')}</div><div class="intel-provider-metric">${headline}</div>${id==='virustotal'&&found?`<div class="intel-counts"><span><i class="dot partial"></i>${stats.malicious||0} malicious</span><span>${stats.suspicious||0} suspicious</span><span>${unsupported} unsupported</span></div><p>${r.fresh_analysis?'Fresh VT analysis':'Existing report'}${r.analysis_date?' · analyzed '+new Date(r.analysis_date*1000).toLocaleDateString('en-GB'):''}. ${r.fresh_analysis?(r.analysis_mode==='REANALYSIS'?'Existing VT file reanalyzed without uploading APK bytes. Zero detections do not guarantee safety.':'Exact APK uploaded with consent. Zero detections do not guarantee safety.'):'Hash lookup only; does not trigger a fresh file scan.'}</p>`:`<p>${missing?'This SHA-256 is absent from this provider’s records. Reputation remains unknown.':found?'This hash has a recorded payload observation. Review it alongside the static evidence.':r?.status==='NOT_CONFIGURED'?'Add the provider API key to the local .env configuration.':esc(r?.detail||s.reputation?.detail||'No external lookup was completed for this scan.')}</p>`}${id==='virustotal'&&s.vt_upload_error?`<div class="notice">${icon('alert')}Fresh analysis was not completed: ${esc(s.vt_upload_error)}. Any existing hash report shown here is separate.</div>`:''}${r?.analysis_id?`<p class="mono">Analysis ID: ${esc(r.analysis_id)}</p>`:''}${r?.signature?`<p class="intel-signature">Signature: ${esc(r.signature)}</p>`:''}<div class="intel-provider-foot">${icon('lock')}${r?.fresh_analysis?(r.analysis_mode==='REANALYSIS'?'Reanalysis requested · no APK upload':'APK uploaded with explicit consent'):'SHA-256 lookup only · no APK upload'}</div></article>`;
 }).join('')}</div>`;
}
function enrichmentResults(){return state.scan?enrichmentPage(false):''}
function enrichmentPage(compact=false){
 const s=state.scan;if(!s)return '';const a=s.ai_explanation,stages=stageSnapshot(s),hosted=a?.provider&&a.provider!=='local',gaps=Object.values(stages).filter(x=>x.status!=='COMPLETED');
 const summary=a?.summary||(s.pipeline?(stages.ai.status==='SKIPPED'?'Hosted AI synthesis was not run for this investigation.':'Hosted AI synthesis could not complete.')+' The collected evidence and unresolved gaps remain available below.':'This earlier investigation contains bounded static evidence. A combined hosted summary is unavailable; review the provider results and gaps below.');
 const headline=hosted?'Intelligence brief':'Investigation summary';
 const metrics={indexed:(s.inventory||[]).filter(x=>['Indexed','Analyzed'].includes(x.status)).length,total:(s.inventory||[]).length};
 return `<section class="intel-brief ${compact?'compact-brief':''}"><div class="intel-brief-head"><div class="eyebrow">Investigation intelligence</div><div class="intel-badges">${tag(hosted?'AI synthesis · '+providerLabel(a.provider):'Evidence overview',hosted?'':'gray')}${tag(s.pipeline?(gaps.length?'Completed with gaps':'Selected checks complete'):'Earlier scan','gray')}</div></div><div class="intel-brief-grid"><div class="intel-narrative"><h2>${headline}</h2><p class="intel-summary">${esc(summary)}</p>${hosted?'<p class="intel-caption">AI interpretation of collected evidence · static findings remain unchanged</p>':''}${!compact?intelligenceList('Key observations',a?.highlights):''}${!compact?intelligenceList('Recommended next steps',a?.recommendations):''}${compact?'<button class="btn intel-detail" data-page="Intelligence">Open full intelligence '+icon('arrow')+'</button>':''}</div><aside class="intel-source-rail" aria-label="Analysis stages"><h3>Evidence sources</h3>${[['static','Static analysis','shield'],['reputation','Reputation','network'],['dynamic','Dynamic execution','android'],['ai','AI intelligence','spark']].map(([key,label,i])=>`<div class="intel-source"><span>${icon(i)}${label}</span>${stageBadge(stages[key].status)}</div>`).join('')}<div class="intel-timing"><div><span>Total investigation</span><strong>${s.pipeline?esc(s.duration)+'s':'Not recorded'}</strong></div><div><span>Static checks</span><strong>${esc(s.static_duration??s.duration)}s</strong></div></div></aside></div><div class="intel-boundary">${icon('info')}Limited analysis supports review, not an APK safety guarantee. Missing records and unobserved behavior remain unknown.</div></section>${!compact?intelligenceSections(a):''}${!compact?reputationCards(s):''}${!compact?vtEvidencePanel(s):''}${!compact?`<div class="intel-details-grid"><section class="panel"><div class="panel-head"><h2>Coverage & unresolved questions</h2></div><div class="intel-detail-body">${intelligenceList('AI-identified uncertainties',a?.uncertainties)}${gaps.map(x=>`<div class="intel-gap">${icon('info')}<p>${esc(x.detail)}</p></div>`).join('')}<p>${metrics.indexed} / ${metrics.total} inventoried files indexed or parsed. Static analysis uses manifest attributes and bounded byte references. Full decompilation and semantic data flow are not configured.</p><p>Firebase Robo provides limited execution evidence; full filesystem, syscall and packet tracing are unavailable.</p></div></section><section class="panel"><div class="panel-head"><h2>Runtime evidence</h2><button class="btn ghost" data-page="Dynamic">Artifacts ${icon('arrow')}</button></div><div class="intel-detail-body">${Object.values(s.dynamic_results||{}).slice(-1).map(d=>`<h3>${esc(providerLabel(d.provider))} · ${esc(d.status==='COMPLETED'?'Execution completed':d.status.replaceAll('_',' ').toLowerCase())}</h3><p>${esc(d.device?.model||'Device not selected')} · Android ${esc(d.device?.android_version||d.device?.version||'unknown')} · ${esc(d.coverage||'LIMITED')} coverage</p><p>${d.observations?.length||0} observations · ${d.artifacts?.filter(x=>x.status==='AVAILABLE').length||0} available artifacts</p>`).join('')||`<h3>Runtime verification unavailable</h3><p>${esc(stages.dynamic.detail)}. No runtime claim can be drawn.</p>`}</div></section></div><section class="panel panel-spaced"><div class="panel-head"><h2>Supporting commentary</h2>${tag('AI text · not evidence','gray')}</div><div class="intel-detail-body"><details><summary>Finding explanations (${a?.findings?.length||0})</summary>${(a?.findings||[]).map(f=>`<article class="intel-finding"><h3>${esc(f.id)} · ${esc(s.findings.find(x=>x.id===f.id)?.title||'Finding')}</h3><p>${esc(f.explanation)}</p></article>`).join('')||'<p>No hosted finding commentary is available.</p>'}</details>${a?.errors?.length?`<details><summary>Provider fallback details</summary>${a.errors.map(x=>`<p>${esc(x.provider)} · ${esc(x.error)}</p>`).join('')}</details>`:''}<div class="intel-refresh"><p>AI synthesis receives normalized collected evidence, including VT metadata and sanitized network/behavior observations. Hash refresh also collects accessible VT details. No APK or source is sent by these refresh actions.</p><button class="btn" data-enrich="reputation">Refresh evidence & intelligence</button><button class="btn" data-enrich="ai/explain">Regenerate intelligence</button></div></div></section>`:''}`;
}
function progressPanel(status,filename,started){
 const stages=status.pipeline?.stages||{static:{status:'RUNNING'},reputation:{status:'PENDING'},dynamic:{status:'PENDING'},ai:{status:'PENDING'}};
 return `<div class="investigation-progress" role="status" aria-live="polite"><div class="progress-orbit">${icon('shield')}</div><div class="eyebrow">Investigation in progress</div><h2>Following the evidence.</h2><p class="progress-current">${esc(status.stage||'Preparing package')}</p><p class="progress-file">${esc(filename)} · ${Math.max(0,Math.floor((Date.now()-started)/1000))}s elapsed</p><div class="pipeline-timeline">${[['static','Static analysis','Manifests, permissions & bounded references'],['reputation','Reputation checks','VirusTotal and URLhaus hash records'],['dynamic','Cloud dynamic execution','Consent required · remote Android Robo test'],['ai','Intelligence synthesis','Combines all collected evidence']].map(([key,label,detail])=>`<div class="pipeline-step ${stages[key].status.toLowerCase()}"><div class="pipeline-step-icon">${stages[key].status==='RUNNING'?'<i class="spinner"></i>':icon(stages[key].status==='COMPLETED'?'checkcircle':stages[key].status==='FAILED'?'alert':'circle')}</div><div><strong>${label}</strong><p>${esc(stages[key].detail||detail)}</p></div>${stageBadge(stages[key].status)}</div>`).join('')}</div><p class="progress-foot">The final report appears after every selected stage finishes or records an explicit gap. Closing this dialog does not stop the investigation.</p></div>`;
}
async function monitorInvestigation(id,filename,started=Date.now()){
 const deadline=Date.now()+150*60*1000;let failures=0;
 while(Date.now()<deadline){
  let status;try{status=await api('/scans/'+id+'/status');failures=0}catch(e){if(/not found|cleared from history/i.test(e.message)){localStorage.removeItem('apktrust-active-scan');throw e}if(++failures>20)throw e;await new Promise(r=>setTimeout(r,1000));continue}
  const form=document.querySelector('#scan-form');if(form)form.innerHTML=progressPanel(status,filename,started);
  if(status.state==='FAILED'){localStorage.removeItem('apktrust-active-scan');throw Error(status.error||'Static analysis failed')}
  if(status.report){state.scan=status.report;state.scans=await api('/scans');state.busy=false;localStorage.removeItem('apktrust-active-scan');closeOverlay();navigate('Overview');toast('Investigation complete · review the intelligence and coverage gaps');return}
  await new Promise(r=>setTimeout(r,1000));
 }
 throw Error('Investigation is still running. Resume it from scan history; no final report has been published.');
}
async function resumeInvestigation(id){
 if(state.busy)return;state.busy=true;
 const scan=state.scans.find(x=>x.id===id);mountOverlay(`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Investigation progress"><div class="modal-head"><h2>Running investigation</h2><button data-close aria-label="Close progress">${icon('close')}</button></div><div class="modal-body" id="scan-form"></div></section></div>`);
 try{await monitorInvestigation(id,scan?.filename||'Uploaded package',(scan?.pipeline?.started_at||Date.now()/1000)*1000)}catch(e){state.busy=false;toast(e.message);closeOverlay()}
}
async function upload(){
 if(!state.file||state.busy)return;state.busy=true;const filename=state.file.name;
 try{
  document.querySelector('#start-scan').disabled=true;document.querySelector('#start-scan').textContent='Starting…';
  const health=await api('/system/health');if(health.pipeline_version!==2)throw Error('The running server uses an older pipeline. Stop it with Ctrl+C and run ./start.sh, then refresh this page.');
  const retain=document.querySelector('#retain-dynamic')?.checked===true,autoAI=document.querySelector('#auto-ai')?.checked===true,autoReputation=document.querySelector('#auto-reputation')?.checked===true,autoDynamic=document.querySelector('#auto-dynamic')?.checked===true;
  const vtUpload=document.querySelector('#vt-upload')?.checked===true;if(vtUpload&&!health.vt_upload_supported)throw Error('Restart ./start.sh to enable VirusTotal file upload.');
  const query=new URLSearchParams({vt_upload:vtUpload,confirm_vt_upload:vtUpload,filename,retain_dynamic:retain,auto_ai:autoAI,auto_reputation:autoReputation,auto_dynamic:autoDynamic,confirm_cloud_upload:autoDynamic});
  const job=await api('/scans?'+query,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:state.file});
  localStorage.setItem('apktrust-active-scan',job.id);document.querySelector('#start-scan').textContent='Investigation running';
  await monitorInvestigation(job.id,filename);
 }catch(e){state.busy=false;const form=document.querySelector('#scan-form');if(form)form.innerHTML=`<div class="notice">${icon('alert')}<div><strong>Investigation could not complete.</strong><p>${esc(e.message)}</p></div></div>`;const button=document.querySelector('#start-scan');if(button){button.disabled=false;button.textContent='Back to upload';button.onclick=()=>{closeOverlay();newScan()}}else toast(e.message)}
}

async function providerTest(button){const id=button.dataset.providerTest;button.disabled=true;button.textContent='Testing…';try{const result=await api('/providers/'+id+'/test',{method:'POST'});state.providers=await api('/providers/status');render();toast(id+': '+result.status+' · '+result.detail)}catch(e){toast(e.message);button.disabled=false;button.textContent='Test connection'}}
async function enrichScan(button){const id=state.scan.id;button.disabled=true;button.textContent='Requesting…';try{const result=await api('/scans/'+id+'/'+button.dataset.enrich,{method:'POST'});if(button.dataset.enrich==='reputation'){button.textContent='Synthesizing collected evidence…';await api('/scans/'+id+'/ai/explain',{method:'POST'})}state.scan=await api('/scans/'+id);state.scans=await api('/scans');render();toast('Enrichment saved. Deterministic findings are unchanged.')}catch(e){toast(e.message);render()}}
function infrastructure(page){if(page==='Sandbox')return dynamicProviderCard();if(page==='Providers')return providersPage();if(page==='Settings')return `<section class="panel"><div class="panel-head"><h2>Workbench preferences</h2></div><div class="settings-list"><div class="setting"><div><h3>Dark appearance</h3><p>Switch between light and dark workbench themes.</p></div><button class="toggle ${document.body.classList.contains('dark')?'':'off'}" role="switch" aria-checked="${document.body.classList.contains('dark')}" aria-label="Dark appearance" data-action="theme"></button></div><div class="setting"><div><h3>Local processing</h3><p>Loopback-only service. Cloud dynamic analysis requires explicit consent.</p></div>${tag('Always on')}</div><div class="setting"><div><h3>Retention</h3><p>Keep normalized reports and evidence. APKs are deleted unless retained explicitly for dynamic analysis.</p></div>${tag('Reports only','gray')}</div><div class="setting"><div><h3>Resource limits</h3><p>256 MiB upload · 16 MiB per indexed file · 128 MiB index budget<br>90 second worker timeout · maximum 2 concurrent scans</p></div>${tag('Bounded')}</div></div></section>`;
if(page==='System health'){let h=state.health;return `<div class="notice">${icon('pulse')}${h?'Local service is healthy. Real capabilities are listed below.':'Checking the local service…'}</div><section class="panel"><div class="panel-head"><h2>Analyzer availability</h2>${tag('Local mode')}</div><div class="settings-list">${[['Archive validation & hash',true,'Streaming intake with path and compression checks'],['Android manifest parser',true,'Text and bounded binary XML'],['Byte-reference index',true,'Contextual signals; no semantic conclusions'],['JADX / data flow',false,'External integration not configured'],['Signing verification',false,'apksigner integration not configured'],['Native semantic analysis',false,'No ELF call graph or Ghidra integration'],['Remote dynamic provider',state.dynamicHealth?.status==='READY','Firebase Test Lab Robo · requires explicit cloud-upload consent'],['AI explanation gateway',state.providers.some(p=>['groq','openrouter','gemini'].includes(p.id)&&p.configured),'Optional server-side adapters; raw APK/source never sent']].map(([name,on,detail])=>`<div class="setting"><div><h3>${name}</h3><p>${detail}</p></div>${tag(on?'Available':'Not configured',on?'':'gray')}</div>`).join('')}</div><div class="table-footer">${h?'Free disk: '+bytes(h.disk_free)+' · Runtime v'+h.version:'Service status unavailable'}</div></section>`}
let info={Sandbox:['box','Runtime analysis is not configured','Static APK analysis works without an emulator. Dynamic behavior requires a separate disposable Android environment with controlled networking.','No runtime claims are made in this build.'],Providers:['spark','Your verdict does not depend on AI','Provider adapters are not connected in this build. Findings include local explanations and evidence without sending APKs or code to hosted models.','No API keys requested. No outbound AI traffic.'],Plugins:['plugin','A deliberately closed trust boundary','Custom plugin execution is not available in this build. Built-in analyzers run in resource-limited subprocesses; arbitrary plugin code is never loaded.','Capability manifests and isolated plugin runners are planned.']}[page];return `<section class="panel"><div class="empty">${icon(info[0])}<h2>${info[1]}</h2><p>${info[2]}</p><p>${info[3]}</p><button class="btn" data-page="System health">Inspect available analyzers ${icon('arrow')}</button></div></section>`}
function uploadLanding(){return `<section class="upload-landing" aria-label="Package upload"><div class="upload-emblem">${brandMark()}</div><div class="eyebrow">Local-first APK investigation</div><h2>Investigate an Android package</h2><p>Static evidence, reputation and runtime observations — brought together in one investigation.</p><input type="file" id="landing-file" accept=".apk,.xapk,.apks" hidden><button id="landing-drop" class="landing-drop">${icon('upload')}<strong>Drop an Android package here</strong><span>or choose a file from your computer</span><small>APK · XAPK · APKS &nbsp; / &nbsp; up to 256 MiB</small><span class="btn primary">Choose package ${icon('arrow')}</span></button><div class="landing-privacy">${icon('lock')}Your package stays on this machine. External enrichment is optional.</div><div class="landing-details"><div><h3>Evidence-backed findings</h3><p>Inspect manifest attributes, API references and their exact origins.</p></div><div><h3>Visible analysis gaps</h3><p>Risk, confidence and coverage stay separate. Unknown stays unknown.</p></div><div><h3>Package-set coverage</h3><p>Base and split APKs are indexed. OBB content is listed as unanalyzed.</p></div></div><div class="notice">${icon('info')}This build performs bounded static checks. Full decompilation and data-flow are not configured. Remote runtime analysis is optional and requires cloud-upload consent.</div></section>`}
function pageContent(){return ({Upload:uploadLanding,Overview:overview,Findings:findings,Coverage:coverage,'Behavior graph':graph,Manifest:manifest,Network:network,Artifacts:artifacts,Dynamic:dynamicPage,Intelligence:enrichmentPage,Scans:history,Rules:rules}[state.page]||(()=>infrastructure(state.page)))()}
function render(){document.querySelector('#app').innerHTML=shell();document.querySelectorAll('[data-width]').forEach(e=>e.style.width=e.dataset.width+'%');bind()}
function bind(){bindInventory();bindDynamic();const vtLoad=document.querySelector("#vt-network-load");if(vtLoad)vtLoad.onclick=async()=>{vtLoad.disabled=true;vtLoad.textContent="Loading relationships…";try{const result=await api("/scans/"+state.scan.id+"/reputation/network",{method:"POST"});state.scan.vt_network=result;render()}catch(e){toast(e.message);vtLoad.disabled=false;vtLoad.textContent="Retry VT lookup"}};document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>resumeInvestigation(b.dataset.resume));const drop=document.querySelector('#landing-drop'),file=document.querySelector('#landing-file');if(drop&&file){drop.onclick=()=>file.click();file.onchange=()=>{if(file.files[0]){const chosen=file.files[0];newScan();selectFile(chosen)}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files[0]){newScan();selectFile(e.dataTransfer.files[0])}}}document.querySelectorAll('[data-provider-test]').forEach(b=>b.onclick=()=>providerTest(b));document.querySelectorAll('[data-enrich]').forEach(b=>b.onclick=()=>enrichScan(b));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-finding]').forEach(b=>{b.onclick=()=>showFinding(b.dataset.finding);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showFinding(b.dataset.finding)}}});document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=()=>{state.scan=state.scans.find(s=>s.id===b.dataset.scan);navigate('Overview')});const search=document.querySelector('#finding-search');if(search)search.oninput=()=>{state.search=search.value;refreshResults()};const sev=document.querySelector('#severity-filter');if(sev)sev.onchange=()=>{state.severity=sev.value;refreshResults()};const rev=document.querySelector('#review-filter');if(rev)rev.onchange=()=>{state.review=rev.value;refreshResults()}}
function refreshResults(){document.querySelector('#finding-results').innerHTML=filteredFindings();document.querySelectorAll('[data-finding]').forEach(b=>{b.onclick=()=>showFinding(b.dataset.finding);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showFinding(b.dataset.finding)}}})}
function clearHistoryModal(){mountOverlay(`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="clear-title"><div class="modal-head"><div><h2 id="clear-title">Clear scan history?</h2><p>Hide saved investigations from this workspace.</p></div><button data-close aria-label="Close clear history">${icon('close')}</button></div><div class="modal-body"><p>Saved reports, reviews and AI explanations will leave the history list. Undo can restore them. API keys and running scans are preserved.</p><div class="notice panel-spaced">${icon('info')}This does not change scanner depth or rescan speed. Every new upload already runs fresh analysis.</div></div><div class="modal-footer"><button class="btn" data-close>Keep history</button><button class="btn primary" id="confirm-clear">Clear history</button></div></section></div>`);document.querySelector('#confirm-clear').onclick=async()=>{const button=document.querySelector('#confirm-clear');button.disabled=true;try{const result=await api('/scans/clear-history',{method:'POST'});state.historyUndo=result.undo_token;localStorage.setItem('apktrust-history-undo',result.undo_token);state.scans=await api('/scans');state.scan=null;closeOverlay();navigate('Scans');toast(result.cleared+' saved investigations cleared')}catch(e){toast(e.message);button.disabled=false}}}
async function undoHistory(){try{await api('/scans/restore-history/'+state.historyUndo,{method:'POST'});state.historyUndo=null;localStorage.removeItem('apktrust-history-undo');state.scans=await api('/scans');navigate('Scans');toast('History restored')}catch(e){toast(e.message)}}
function action(name){if(name==='clear-history')clearHistoryModal();else if(name==='undo-history')undoHistory();else if(name==='new'||name==='rerun')newScan();else if(name==='menu')document.querySelector('.sidebar').classList.toggle('open');else if(name==='theme'){document.body.classList.toggle('dark');localStorage.setItem('apktrust-theme',document.body.classList.contains('dark')?'dark':'light');render()}else if(name==='search'){searchModal()}else if(name==='copy'){navigator.clipboard.writeText(state.scan.sha256).then(()=>toast('SHA-256 copied')).catch(()=>toast('Clipboard unavailable in this browser'))}else if(name==='export')exportModal();else if(name==='notices'){navigate('Coverage')}}
let returnFocus=null;
function mountOverlay(content){returnFocus=document.activeElement;document.querySelector('#overlay').innerHTML=content;document.body.classList.add('overlay-open');document.body.style.overflow='hidden';document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeOverlay);document.querySelector('.modal-backdrop,.drawer-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop')||e.target.classList.contains('drawer-backdrop'))closeOverlay()};document.querySelector('#overlay button')?.focus()}
function closeOverlay(){if(state.busy)return;document.querySelector('#overlay').innerHTML='';document.body.classList.remove('overlay-open');document.body.style.overflow='';returnFocus?.focus()}
function showFinding(id){const f=state.scan.findings.find(f=>f.id===id);if(!f)return;mountOverlay(`<div class="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="finding-title"><div class="modal-head"><div><div class="eyebrow">Finding ${esc(f.id)} / Evidence review</div><p>${esc(f.rule)}</p></div><button data-close aria-label="Close finding">${icon('close')}</button></div><div class="drawer-body"><h1 id="finding-title">${esc(f.title)}</h1><div class="drawer-tags">${severity(f.severity)}${tag(f.confidence+' confidence')}${tag(f.status,'gray')}${f.evidence_tier?tag(f.evidence_tier.replaceAll('_',' '),'gray'):''}${f.assessment_type?tag(f.assessment_type,'gray'):''}${f.origin==='Dynamic'?tag('DYNAMIC · Firebase Test Lab'):tag('STATIC','gray')}</div><p>${esc(f.description)}</p><div class="drawer-section"><h3>Evidence & provenance</h3>${f.evidence.map(e=>`<div class="evidence-block"><div class="evidence-top"><strong>${esc(e.id)}</strong><span>${f.origin==='Dynamic'?'FIREBASE_TEST_LAB':state.scan.demo?'Illustrative fixture':'STATIC artifact reference'}</span></div><div class="evidence-path">${esc(e.path)}<br>${esc(e.location)}</div><pre><code>${esc(e.snippet)}</code></pre><div class="evidence-bottom">Analyzer: ${esc(e.analyzer)}<br>Artifact SHA-256: ${esc(e.sha256)}${e.container_sha256?'<br>Container SHA-256: '+esc(e.container_sha256):''}</div></div>`).join('')}</div>${f.runtime?`<div class="drawer-section"><h3>Observed at runtime</h3><pre>${esc(JSON.stringify(f.runtime,null,2))}</pre><p>Evidence source: ${esc(f.evidence_source)}</p></div>`:''}${f.runtime_evidence?.length?`<div class="drawer-section"><h3>Related runtime evidence</h3><pre>${esc(JSON.stringify(f.runtime_evidence,null,2))}</pre></div>`:''}<div class="drawer-section"><h3>Possible benign explanation</h3><p>${esc(f.benign)}</p></div><div class="drawer-section"><h3>Recommended review</h3><p>${esc(f.remediation)}</p></div><div class="drawer-section"><h3>Analyst decision</h3><p class="review-note">Review status is saved locally and does not alter deterministic evidence.</p><div class="review-controls">${['Confirmed','Dismissed','Needs review'].map(s=>`<button class="btn ${s===f.status?'primary':''}" data-review="${s}">${icon(s==='Confirmed'?'check':s==='Dismissed'?'close':'eye')}${s}</button>`).join('')}</div></div></div></section></div>`);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{try{if(!state.scan.demo)await api(`/scans/${state.scan.id}/findings/${f.id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:b.dataset.review})});f.status=b.dataset.review;render();showFinding(id);toast('Review saved'+(state.scan.demo?' for this demo session':''))}catch(e){toast(e.message)}})}
function newScan(){if(state.busy){toast('An investigation is already running. Follow it in scan history.');return}state.file=null;mountOverlay(`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="new-title"><div class="modal-head"><div><div class="eyebrow">A new investigation</div><h2 id="new-title">Understand before you install.</h2><p>Start with a package. Follow the evidence.</p></div><button data-close aria-label="Close new scan">${icon('close')}</button></div><div class="modal-body" id="scan-form"><input type="file" id="apk-file" accept=".apk,.xapk,.apks" hidden><button class="dropzone full-width" id="dropzone">${icon('upload')}<h3>Drop your APK, XAPK or APKS here</h3><p>or <strong>browse files</strong> to choose a package</p><p>APK / XAPK / APKS · up to 256 MiB · processed locally</p></button><label class="field-label">Analysis profile</label><div class="option-card">${icon('shield')}<div><h3>Static · bounded investigation</h3><p>Package-set intake, manifests, reference signals & endpoints.<br>Explicit coverage ledger for every inventoried file.</p></div>${tag('Available')}</div><div class="options-row"><div>Remote dynamic analysis<small>Firebase Test Lab Robo · included in this investigation when consented</small></div><span id="upload-dynamic-status">${tag('Optional','gray')}</span></div><label class="dynamic-consent cloud-upload-choice"><input id="auto-dynamic" type="checkbox"><span><strong>Run cloud dynamic analysis with this investigation.</strong><br>I understand this APK will leave this machine and be uploaded to Google Firebase Test Lab. Robo may take several minutes.</span></label><label class="dynamic-consent"><input id="retain-dynamic" type="checkbox">Keep this APK locally after the investigation for optional reruns.</label><div class="options-row"><div>AI explanation<small>Runs last and combines static, reputation and available runtime evidence</small></div><span id="upload-ai-status">${tag('Checking setup…','gray')}</span></div><label class="dynamic-consent"><input id="auto-ai" type="checkbox" checked>Generate a full intelligence report from static/runtime evidence and collected VT metadata, detections, sanitized observables and behavior. VT public package metadata may be sent to AI. No APK, credentials or raw source upload.</label><label class="dynamic-consent"><input id="auto-reputation" type="checkbox" checked>Automatically query VirusTotal and URLhaus, then collect available VT metadata, engine, sandbox and relationship evidence. Extra API calls may take several minutes. No APK upload unless selected below.</label><label class="dynamic-consent cloud-upload-choice"><input id="vt-upload" type="checkbox"><span><strong>Request fresh VirusTotal analysis for this public APK.</strong><br>APKTrust checks the SHA-256 first. Existing files are reanalyzed without upload. If not found, I consent to uploading this APK, which may be shared with the VT security community. Engine analysis can take several minutes. Standalone APK only; no private files.</span></label><div id="upload-error" class="error-msg" role="alert"></div></div><div class="modal-footer"><p>${icon('lock')}External APK uploads run only when the corresponding consent checkbox is checked.</p><button class="btn primary" id="start-scan" disabled>${icon('scan')}Start investigation</button></div></section></div>`);api('/dynamic/providers').then(p=>{state.dynamicHealth=p[0];const el=document.querySelector('#upload-dynamic-status');if(el)el.innerHTML=tag(p[0].status,p[0].status==='READY'?'':'gray')}).catch(()=>{});const file=document.querySelector('#apk-file'),drop=document.querySelector('#dropzone');drop.onclick=()=>file.click();file.onchange=()=>selectFile(file.files[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');selectFile(e.dataTransfer.files[0])};document.querySelector('#start-scan').onclick=upload;api('/providers/status').then(providers=>{state.providers=providers;const badge=document.querySelector('#upload-ai-status');if(badge)badge.innerHTML=tag(providers.some(p=>['groq','openrouter','gemini'].includes(p.id)&&p.configured)?'Automatic after scan':'No AI key configured',providers.some(p=>['groq','openrouter','gemini'].includes(p.id)&&p.configured)?'':'gray')}).catch(()=>{const badge=document.querySelector('#upload-ai-status');if(badge)badge.innerHTML=tag('Setup check unavailable','orange')})}
function selectFile(file){const error=document.querySelector('#upload-error');if(!file)return;if(!/\.(apk|xapk|apks)$/i.test(file.name)||file.size>256*1024**2){error.textContent='Choose an .apk, .xapk or .apks file no larger than 256 MiB. AAB is not supported.';state.file=null;document.querySelector('#start-scan').disabled=true;return}state.file=file;const vt=document.querySelector('#vt-upload');if(vt){vt.checked=false;vt.disabled=!/\.apk$/i.test(file.name)}error.textContent='';document.querySelector('#dropzone').innerHTML=`${icon('android')}<h3>${esc(file.name)}</h3><p>${bytes(file.size)} · Ready for local analysis</p><p><strong>Click to choose a different file</strong></p>`;document.querySelector('#start-scan').disabled=false}

function download(data,filename,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportModal(){mountOverlay(`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="export-title"><div class="modal-head"><div><h2 id="export-title">Export investigation</h2><p>Keep the findings, evidence and analysis gaps together.</p></div><button data-close aria-label="Close export">${icon('close')}</button></div><div class="modal-body"><div class="notice">${icon('info')}${state.scan.demo?'Demo exports are clearly marked as illustrative data.':'Reports include incomplete coverage and analyzer provenance.'}</div><label class="dynamic-consent"><input id="export-screenshots" type="checkbox">Include screenshot references in export (may reveal sensitive artifact names)</label>${[['json','JSON','Complete normalized evidence and inventory'],['html','HTML','Self-contained, safely escaped report'],['sarif','SARIF','Static findings for code-review workflows']].map(([format,title,text])=>`<button class="scan-card full-width" data-export="${format}">${icon('file')}<div class="scan-info"><h3>${title}</h3><p>${text}</p></div>${icon('download')}</button>`).join('')}</div></section></div>`);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{const s=state.scan,f=b.dataset.export;if(!s.demo){const a=document.createElement('a');a.href=`/api/v1/scans/${s.id}/report.${f}?include_screenshots=${document.querySelector('#export-screenshots').checked}`;a.download='apktrust-'+s.id+'.'+f;a.click()}else if(f==='json')download(JSON.stringify(s,null,2),'apktrust-DEMO.json','application/json');else if(f==='html')download('<!doctype html><html lang="en"><meta charset="utf-8"><title>APKTrust DEMO report</title><h1>APKTrust — DEMO / illustrative report</h1><p>This is not an analyzed package.</p><pre>'+esc(JSON.stringify(s,null,2))+'</pre></html>','apktrust-DEMO.html','text/html');else download(JSON.stringify({version:'2.1.0',runs:[{tool:{driver:{name:'APKTrust DEMO'}},results:s.findings.map(f=>({ruleId:f.rule,level:'note',message:{text:'DEMO: '+f.title}}))}]},null,2),'apktrust-DEMO.sarif','application/json');toast('Report downloaded');closeOverlay()})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();document.querySelector('.sidebar')?.classList.remove('open')}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('search')}if(document.body.classList.contains('overlay-open')&&e.key==='Tab'){let focusable=[...document.querySelectorAll('#overlay button:not(:disabled),#overlay input:not([hidden]),#overlay select,#overlay [tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
if(localStorage.getItem('apktrust-theme')==='dark')document.body.classList.add('dark');
document.addEventListener('DOMContentLoaded',()=>{render();Promise.allSettled([api('/scans'),api('/system/health'),api('/providers/status'),api('/rules')]).then(([scans,health,providers,catalog])=>{if(scans.status==='fulfilled')state.scans=scans.value;if(health.status==='fulfilled')state.health=health.value;if(providers.status==='fulfilled')state.providers=providers.value;if(catalog.status==='fulfilled')state.ruleCatalog=catalog.value;render();const active=localStorage.getItem('apktrust-active-scan');if(active)resumeInvestigation(active)});});

function overviewCharts(s){
 const counts=['critical','high','medium','low','info'].map(k=>[k,s.findings.filter(f=>f.severity===k).length]),max=Math.max(1,...counts.map(x=>x[1]));
 const stages=[['Complete',s.coverage.filter(x=>x.status==='Complete').length],['Partial / failed',s.coverage.filter(x=>['Partial','Failed'].includes(x.status)).length],['Not run',s.coverage.filter(x=>x.status==='Not run').length]],total=s.coverage.length||1,length=2*Math.PI*44;
 return `<div class="overview-charts"><section class="panel"><div class="panel-head"><h2>Finding severity</h2><span class="chart-caption">${s.findings.length} findings · static & runtime</span></div><div class="severity-chart" role="img" aria-label="Finding severity: ${counts.map(([k,n])=>k+' '+n).join(', ')}">${counts.map(([k,n])=>`<div class="chart-bar-row"><span>${k[0].toUpperCase()+k.slice(1)}</span><div class="chart-bar-track"><i class="chart-bar ${k}" data-width="${n/max*100}"></i></div><strong>${n}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Analysis coverage</h2><button class="btn ghost" data-page="Coverage">View gaps ${icon('arrow')}</button></div><div class="coverage-chart"><svg viewBox="0 0 110 110" role="img" aria-label="${s.coverage_percent} percent analyzer stage completion"><circle cx="55" cy="55" r="44" class="chart-ring-track"/><circle cx="55" cy="55" r="44" class="chart-ring-value" stroke-dasharray="${length*s.coverage_percent/100} ${length}"/><text x="55" y="54" text-anchor="middle">${s.coverage_percent}%</text><text x="55" y="70" text-anchor="middle" class="chart-ring-label">stages complete</text></svg><div class="chart-legend">${stages.map(([label,n])=>`<div><span>${label}</span><strong>${n}</strong></div>`).join('')}<p>Stage completion is not code coverage or a safety score.</p></div></div></section></div>`;
}
function searchModal(){
 if(state.busy)return;
 mountOverlay(`<div class="modal-backdrop"><section class="modal search-modal" role="dialog" aria-modal="true" aria-labelledby="search-title"><div class="modal-head"><h2 id="search-title">Search findings</h2><button data-close aria-label="Close search">${icon('close')}</button></div><div class="modal-body"><label class="input-wrap">${icon('search')}<input id="modal-search" type="search" placeholder="Title, rule, category or evidence…" aria-label="Search investigation findings"></label><div id="search-hits" aria-live="polite"></div></div><div class="modal-footer"><span>Enter opens the first result · Escape closes</span><button class="btn" id="all-findings" ${state.scan?'':'disabled'}>All findings ${icon('arrow')}</button></div></section></div>`);
 const input=document.querySelector('#modal-search'),hits=document.querySelector('#search-hits');
 function update(){const q=input.value.trim().toLowerCase(),rows=(state.scan?.findings||[]).filter(f=>[f.id,f.title,f.rule,f.category,...(f.evidence||[]).map(e=>e.path+' '+e.snippet)].join(' ').toLowerCase().includes(q));hits.innerHTML=state.scan?`<p class="search-count">${rows.length} matching findings in ${esc(state.scan.package)}</p>${rows.slice(0,30).map(f=>`<button class="search-hit" data-search-finding="${esc(f.id)}"><span>${severity(f.severity)}<strong>${esc(f.title)}</strong><small>${esc(f.id)} · ${esc(f.category)} · ${esc(f.rule)}</small></span>${icon('chevron')}</button>`).join('')||'<div class="empty"><h3>No matching findings</h3><p>Try another keyword or inspect all findings.</p></div>'}${rows.length>30?'<p>Showing the first 30 matches. Refine your search.</p>':''}`:'<div class="empty"><h3>No investigation selected</h3><p>Open a saved scan or upload a package to search its findings.</p></div>';hits.querySelectorAll('[data-search-finding]').forEach(b=>b.onclick=()=>{closeOverlay();showFinding(b.dataset.searchFinding)});}
 input.oninput=update;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();hits.querySelector('[data-search-finding]')?.click()}};document.querySelector('#all-findings').onclick=()=>{const q=input.value;closeOverlay();navigate('Findings');state.search=q;render()};update();input.focus();
}
function vtNetworkPanel(){const s=state.scan,n=(s.vt_network?.checked>s.vt_intelligence?.checked?s.vt_network:vtNetworkFromEvidence(s))||s.vt_network,vt=s.reputation?.results?.find(r=>r.provider==='virustotal'),meta=vt?.file_metadata;
 return `<section class="panel panel-spaced"><div class="panel-head"><div class="title-wrap"><span class="provider-mark">${icon('scan')}</span><div><h2>VirusTotal network intelligence</h2><div class="panel-sub">External report evidence · ${n?'checked '+new Date(n.checked*1000).toLocaleString():'not queried'}</div></div></div><button class="btn" id="vt-network-load" ${vt?.status==='FOUND'?'':'disabled'}>${n?'Refresh':'Load'} VT relationships</button></div><div class="intel-detail-body"><p>Queries existing contacted domains, IPs and URLs for this SHA-256 (up to 3 API requests, 40 entries each). No APK upload or new sandbox execution. Access depends on your API plan and report availability.</p>${meta?`<div class="vt-metadata">${[['File type',meta.type_description],['VT submissions',meta.times_submitted],['First submitted',meta.first_submission_date?new Date(meta.first_submission_date*1000).toLocaleDateString():null]].filter(x=>x[1]!=null).map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`:''}${n?(n.relationships||[]).map(r=>`<details class="vt-relationship" open><summary>${esc(r.label)} · ${r.items.length} returned ${r.truncated?'(partial)':''} ${tag(r.status,'gray')}</summary>${r.detail?`<p>${esc(r.detail)}</p>`:''}${r.items.length?`<div class="table-wrap"><table><thead><tr><th>Observable</th><th>VT detections</th><th>Context</th></tr></thead><tbody>${r.items.map(x=>`<tr><td class="mono">${esc(x.value)}</td><td>${x.malicious} malicious / ${x.suspicious} suspicious</td><td>${esc(x.country||'—')}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`).join(''):`<div class="notice">${icon('info')}${vt?.status==='FOUND'?'Additional relationships have not been queried.':'An existing VirusTotal file report is required. Run hash reputation checks first.'}</div>`}<p class="intel-caption">VT observations describe its existing report, not connections observed by APKTrust. Missing relationships do not establish absence of network behavior.</p></div></section>`;
}

function intelligenceSections(a){return a?.sections?.length?`<section class="panel panel-spaced"><div class="panel-head"><h2>Intelligence assessment</h2>${tag('AI interpretation','gray')}</div><div class="intel-detail-body">${a.sections.map(x=>`<article class="intel-section-report"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><div class="intel-counts">${(x.evidence_ids||[]).map(id=>tag(id,'gray')).join('')}</div></article>`).join('')}</div></section>`:''}
function vtNetworkFromEvidence(s){const groups=s.vt_intelligence?.groups?.filter(g=>['VT-CONTACTED-DOMAINS','VT-CONTACTED-IPS','VT-CONTACTED-URLS'].includes(g.id));if(!groups?.length)return null;return {checked:s.vt_intelligence.checked,relationships:groups.map(g=>({label:g.label,status:g.status,detail:g.detail,truncated:g.truncated,items:(Array.isArray(g.data)?g.data:[]).map(x=>({value:x.observable,malicious:x.attributes?.last_analysis_stats?.malicious||0,suspicious:x.attributes?.last_analysis_stats?.suspicious||0,country:x.attributes?.country}))}))}}
